--- a/src/Prescriptions.tsx
+++ b/src/Prescriptions.tsx
@@ -1,18 +1,35 @@
 import type { Prescription } from './types'

 export function Prescriptions({ items, onChange }: Props) {
+  function remove(index: number) {
+    onChange(items.filter((_, i) => i !== index))
+  }
+
+  if (items.length === 0) {
+    return <p className="empty">Назначений пока нет</p>
+  }
+
   return (
     <ul>
-      {items.map((item) => <Row key={item.id} item={item} />)}
+      {items.map((item, i) => (
+        <Row key={i} item={item} onRemove={() => remove(i)} />
+      ))}
     </ul>
   )
 }
